  "findings": [
    {
      "benefit": "Death",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "Empirical SD of yearly A/E is about 0.22-0.23, versus a Poisson 1/sqrt(E) expectation of roughly 0.035-0.065; largest excursions are 2018 AE 1.522 and 2019 AE 0.734, while the aggregate A/E is only 0.997.",
      "confidence": 0.8,
      "evidence": [
        "artifacts/ae_death_by_year.csv shows Death A/E of 0.868, 1.084, 1.248, 1.522, 0.734, 1.137, 0.942, 0.908, 0.925, 0.884 from 2015 to 2024.",
        "The empirical year-to-year standard deviation of Death A/E is materially larger than the Poisson benchmark of 1/sqrt(expected claims), indicating overdispersion rather than ordinary claim-count noise.",
        "summary.json shows Death overall A/E of 0.997, so the issue is not a simple persistent aggregate level shift but excess dispersion around baseline."
      ],
      "recommended_action": "Do not use Poisson year-level z-scores for Death. Investigate claims-data integrity, exposure-claims matching, large-claim concentration, coding/reporting changes, and segmentation effects; review mortality assumptions and consider a higher-variance or empirical-Bayes treatment in pricing and valuation."
    }
  ]
}

